%--------------------------------------------------------------------------
%findTrialType
%By: Brielle
%Date: 4/11/24
%General Description: Will take the trial structure generated by
%readAnalyzePlotBehData or add ons with neural activity analysis and pull out
%trials of a particular type.
%Assumptions: 
% -       that your trial type is one of a set number of types. For example
%         if you want 3s trials from the variable cue length trials, will generate
%         an error, because task only uses 2s, 1s, 500ms, and 50 ms
%Inputs: 
% -     field: the field to look for your trial type. Should be a field in your
%       trial stucture, e.g. 'previousChoice' 
% -     type: within that field, which type are you looking for, e.g. 'Correct'
% -     trials: data structure with trial information from a behavioral session
%Outputs: 
% -     index: the trial numbers that correspond to your trial type
%--------------------------------------------------------------------------

function index = findTrialType(field, type, trials)

if length(trials) > 1
    if isa(trials(2).(field),'char')  || isa(trials(10).(field),'char') || isa(trials(15).(field),'char')
    fun = @(x) strcmp(trials(x).(field) ,type); %function for fields where answers are character 
    else
        fun = @(x) trials(x).(field) == type; %function for fields where answers are doubles
    end
    index = find(arrayfun(fun, 1:numel(trials))); %find index
else
    index = NaN;
end

end